function Glyph({ name, family = "signal", size = 28 }: { name: IconName; family?: IconFamily; size?: number }) {
  const common = { stroke: "currentColor", strokeWidth: family === "evidence" ? 2.2 : 1.7, strokeLinecap: "round" as const, strokeLinejoin: "round" as const };
  const mark: Record<IconName, ReactNode> = {
    agent: <><path d="M8 19c1.4-3.2 3.7-4.8 7-4.8s5.6 1.6 7 4.8" {...common}/><path d="M9 9.5h12M11 9.5l1.3-4h5.4l1.3 4" {...common}/><path d="M10.5 11.5c.8 2.4 2.3 3.6 4.5 3.6s3.7-1.2 4.5-3.6" {...common}/><path d="M8.7 11.5h12.6" {...common}/></>,
    civilian: <><circle cx="15" cy="9" r="4" {...common}/><path d="M7.5 23c.8-5.1 3.3-7.7 7.5-7.7s6.7 2.6 7.5 7.7" {...common}/><path d="M11.5 20h7" {...common}/></>,
    question: <><path d="M10.5 10a4.7 4.7 0 0 1 9 1.8c0 3.5-4.5 3.8-4.5 6" {...common}/><path d="M15 22.6v.1" {...common}/><circle cx="15" cy="15" r="12" {...common}/></>,
    draw: <><path d="M7 22l1.2-5.6L20.8 3.8l4.4 4.4-12.6 12.6L7 22Z" {...common}/><path d="m17.8 6.8 4.4 4.4M8.2 16.4l4.4 4.4" {...common}/><path d="M5 25h20" {...common}/></>,
    vote: <><path d="M6 13h18v12H6z" {...common}/><path d="m10 13 5-8 5 8" {...common}/><path d="M11 19h8" {...common}/></>,
    timer: <><circle cx="15" cy="16" r="10" {...common}/><path d="M15 16V9M12 3h6M22.5 7.5l2-2" {...common}/></>,
  };
  return (
    <svg width={size} height={size} viewBox="0 0 30 30" fill="none" aria-hidden="true" className={`spy-glyph spy-glyph-${family}`}>
      {family === "signal" && <circle cx="15" cy="15" r="13.5" stroke="currentColor" strokeOpacity=".18" strokeDasharray="2 3" />}
      {family === "optic" && <><path d="M3 9V3h6M21 3h6v6M27 21v6h-6M9 27H3v-6" stroke="currentColor" strokeWidth="1.4"/><circle cx="15" cy="15" r="12" stroke="currentColor" strokeOpacity=".15"/></>}
      {mark[name]}
    </svg>
  );
}

function DeviceLabel({ tv = false }: { tv?: boolean }) {
  return <div className="spy-device-label"><span>{tv ? "Игровое поле · TV" : "Телефон"}</span><b>{tv ? "1920 × 1080" : "390 × 844"}</b></div>;
}

function PhoneSecret({ concept }: { concept: Concept }) {
  const [revealed, setRevealed] = useState(false);
  const show = (event?: PointerEvent<HTMLButtonElement>) => {
    if (event) event.currentTarget.setPointerCapture(event.pointerId);
    setRevealed(true);
  };
  const hide = () => setRevealed(false);
  const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    if (event.key === " " || event.key === "Enter") { event.preventDefault(); setRevealed(true); }
  };
  const onKeyUp = (event: KeyboardEvent<HTMLButtonElement>) => {
    if (event.key === " " || event.key === "Enter") { event.preventDefault(); setRevealed(false); }
  };
  return (
    <div className="spy-device-column">
      <DeviceLabel />
      <div className="spy-phone-shell">
        <div className={`spy-phone-screen phone-${concept.id}`}>
          <div className="spy-phone-status"><span>22:41</span><i>● ● ●</i></div>
          <header className="spy-phone-header"><span>ДЕЛО 01</span><b>ТОЛЬКО ДЛЯ ВАС</b></header>
          <main className="spy-secret-main">
            <div className="spy-secret-heading">
              <span>СЕКРЕТНАЯ РОЛЬ</span>
              <h3>{revealed ? "НЕ ВЫДАЙТЕ СЕБЯ" : "УЗНАЙТЕ ЗАДАНИЕ"}</h3>
              <p>{revealed ? "Отпустите экран, чтобы скрыть сведения" : "Убедитесь, что никто не видит экран"}</p>
            </div>
            <button
              type="button"
              className={`spy-secret-card ${revealed ? "is-revealed" : ""}`}
              aria-label="Удерживайте, чтобы открыть секретную роль"
              onPointerDown={show}
              onPointerUp={hide}
              onPointerCancel={hide}
              onPointerLeave={hide}
              onKeyDown={onKeyDown}
              onKeyUp={onKeyUp}
              onContextMenu={(event) => event.preventDefault()}
            >
              {revealed ? (
                <div className="spy-role-open">
                  <div className="spy-role-icon"><Glyph name="agent" family={concept.id === "classified" ? "evidence" : concept.id === "surveillance" ? "optic" : "signal"} size={76}/></div>
                  <span>ВАША РОЛЬ</span>
                  <h4>ШПИОН</h4>
                  <div className="spy-redaction">СЕКРЕТНОЕ СЛОВО ОТСУТСТВУЕТ</div>
                  <p>Слушайте ответы. Вычислите слово. Не дайте себя раскрыть.</p>
                </div>
              ) : (
                <div className="spy-role-closed">
                  <div className="spy-classified-mark">{concept.id === "classified" ? "ДОСЬЕ" : "SPY"}</div>
                  <div className="spy-scan-ring"><Glyph name="agent" family={concept.id === "classified" ? "evidence" : concept.id === "surveillance" ? "optic" : "signal"} size={56}/></div>
                  <b>УДЕРЖИВАЙТЕ</b>
                  <p>Данные исчезнут, когда вы отпустите экран</p>
                </div>
              )}
            </button>
          </main>
          <footer className="spy-phone-footer"><i/> Защищённый просмотр</footer>
        </div>
      </div>
    </div>
  );
}

