function ConceptSection({ concept, selected, onSelect }: { concept: Concept; selected: boolean; onSelect: () => void }) {
  return (
    <section id={concept.id} className={`spy-concept ${selected ? "is-selected" : ""}`} style={{ "--accent": concept.accent, "--secondary": concept.secondary, "--concept-font": concept.font } as CSSProperties}>
      <div className="spy-concept-intro">
        <div className="spy-concept-number">{concept.number}</div>
        <div><span>{concept.eyebrow}</span><h2>{concept.name}</h2><p>{concept.description}</p><div className="spy-tags">{concept.tags.map(tag => <i key={tag}>{tag}</i>)}</div></div>
        <button type="button" onClick={onSelect}>{selected ? "Вариант отмечен" : "Отметить вариант"}</button>
      </div>
      <div className="spy-devices"><PhoneSecret concept={concept}/><TvQuestion concept={concept}/></div>
      <DrawExample concept={concept}/>
    </section>
  );
}

function FlowPhoneHeader({ phase, round = "РАУНД 1" }: { phase: string; round?: string }) {
  return (
    <>
      <div className="flow-phone-status"><span>22:41</span><i>● ● ●</i></div>
      <header className="flow-phone-header"><div><Glyph name="agent" size={24}/><b>ШПИОН</b></div><span>{round}<small>{phase}</small></span></header>
    </>
  );
}

function FlowPhone({ phase }: { phase: FlowPhaseId }) {
  const players = ["Анастасия", "Максим", "Лена", "Сергей"];
  const body = (() => {
    if (phase === "mode") return (
      <div className="flow-phone-body flow-mode">
        <span className="flow-kicker">НОВАЯ ОПЕРАЦИЯ</span><h3>Выберите формат расследования</h3><p>Режим определяет, как участники будут оставлять улики.</p>
        <button type="button" className="flow-mode-card is-primary"><Glyph name="question" size={34}/><span><b>УГАДАЙ СЛОВО</b><small>Задавайте вопросы по цепочке</small></span><i>→</i></button>
        <button type="button" className="flow-mode-card"><Glyph name="draw" size={34}/><span><b>НАРИСУЙ</b><small>Оставляйте улики на холсте</small></span><i>→</i></button>
        <div className="flow-host-note"><i/><span>Только ведущий выбирает режим</span></div>
      </div>
    );
    if (phase === "briefing") return (
      <div className="flow-phone-body flow-briefing">
        <span className="flow-kicker">ДАННЫЕ ПОЛУЧЕНЫ</span><h3>Задание сохранено</h3><p>Секретное слово снова скрыто. Его можно кратко посмотреть во время раунда.</p>
        <div className="flow-brief-card"><div className="flow-brief-orbit"><Glyph name="civilian" size={60}/></div><span>ВАША СТОРОНА</span><b>МИРНЫЙ</b><small>КАТЕГОРИЯ · ПУТЕШЕСТВИЯ</small><em>СЛОВО ЗАЩИЩЕНО</em></div>
        <button type="button" className="flow-main-button">УДЕРЖИВАТЬ, ЧТОБЫ ВСПОМНИТЬ</button><div className="flow-progress"><i style={{width:"75%"}}/><span>6 ИЗ 8 ГОТОВЫ</span></div>
      </div>
    );
    if (phase === "question") return (
      <div className="flow-phone-body flow-question">
        <div className="flow-round-row"><span>04:12</span><b>ПУТЕШЕСТВИЯ</b></div><span className="flow-kicker">ВАШ ХОД</span><h3>Задайте вопрос Максиму</h3>
        <div className="flow-target-card"><div className="flow-avatar">М</div><div><small>АДРЕСАТ</small><b>МАКСИМ</b><span>После ответа он продолжит цепочку</span></div></div>
        <div className="flow-rule"><Glyph name="question" size={24}/><p>Спросите так, чтобы мирные узнали слово, но шпион не получил прямую подсказку.</p></div>
        <button type="button" className="flow-main-button">ВОПРОС ЗАДАН · ПЕРЕДАТЬ ХОД</button><button type="button" className="flow-ghost-button">УДЕРЖИВАТЬ, ЧТОБЫ ВСПОМНИТЬ СЛОВО</button>
      </div>
    );
    if (phase === "draw") return (
      <div className="flow-phone-body flow-drawing">
        <div className="flow-round-row"><span>00:38</span><b>РИСУЕТЕ ВЫ</b></div><span className="flow-kicker">СЕКРЕТНОЕ СЛОВО</span><h3>МАЯК</h3><p>Оставьте улику без букв и цифр.</p>
        <div className="flow-canvas"><svg viewBox="0 0 280 260"><path d="M38 222h204M89 220l25-114h52l25 114M114 106l26-52 26 52M106 150h68M103 177h74M140 54V24M140 24l55 18M57 83l50 28M223 83l-50 28"/></svg><span>ХОЛСТ СИНХРОНИЗИРУЕТСЯ С TV</span><button type="button">↶</button></div>
        <button type="button" className="flow-main-button">ГОТОВО · ПЕРЕДАТЬ ХОД</button>
      </div>
    );
    if (phase === "discussion") return (
      <div className="flow-phone-body flow-discussion">
        <span className="flow-kicker">ОБЩИЙ КАНАЛ ОТКРЫТ</span><div className="flow-big-timer"><svg viewBox="0 0 180 180"><circle cx="90" cy="90" r="78"/><circle className="progress" cx="90" cy="90" r="78"/></svg><b>01:34</b><small>ДО ГОЛОСОВАНИЯ</small></div><h3>Сверьте показания</h3><p>Обсудите улики и назовите тех, чьи ответы звучали подозрительно.</p><div className="flow-people-line">{players.map((name, index)=><i key={name} className={index===2?"suspect":""}>{name[0]}</i>)}</div><div className="flow-host-note"><i/><span>Ведущий откроет голосование</span></div>
      </div>
    );
    if (phase === "voting") return (
      <div className="flow-phone-body flow-voting">
        <div className="flow-round-row"><span>00:24</span><b>ВЫБОР ЗАШИФРОВАН</b></div><span className="flow-kicker">ФИНАЛЬНОЕ РЕШЕНИЕ</span><h3>Кто здесь шпион?</h3><p>Выберите одного участника. После подтверждения изменить голос нельзя.</p>
        <div className="flow-vote-list">{players.slice(1).map((name,index)=><button type="button" key={name} className={index===1?"selected":""}><i>{name[0]}</i><b>{name}</b><span>{index===1?"ВЫБРАН":""}</span></button>)}</div><button type="button" className="flow-main-button">ПОДТВЕРДИТЬ · ЛЕНА</button>
      </div>
    );
    if (phase === "spyGuess") return (
      <div className="flow-phone-body flow-spy-guess">
        <span className="flow-kicker red">ВАС РАСКРЫЛИ</span><div className="flow-alert-orbit"><Glyph name="agent" size={68}/></div><h3>Последний шанс</h3><p>Угадайте секретное слово и перехватите победу.</p><label><span>ВАША ВЕРСИЯ</span><input value="Аэропорт" readOnly aria-label="Версия шпиона"/></label><div className="flow-category-line"><span>КАТЕГОРИЯ</span><b>ПУТЕШЕСТВИЯ</b></div><button type="button" className="flow-main-button danger">ОТПРАВИТЬ ОТВЕТ</button><small className="flow-attempt-note">ПОПЫТКА ТОЛЬКО ОДНА</small>
      </div>
    );
    if (phase === "verdict") return (
      <div className="flow-phone-body flow-verdict">
        <span className="flow-kicker">ТРЕБУЕТСЯ ПРОВЕРКА</span><h3>Ответ можно засчитать?</h3><p>Автоматическая проверка не нашла точного совпадения. Сравните ответы.</p><div className="flow-compare"><div><span>ОТВЕТ ШПИОНА</span><b>АЭРОПОРТ</b></div><i>≠</i><div><span>СЕКРЕТНОЕ СЛОВО</span><b>АЭРОДРОМ</b></div></div><button type="button" className="flow-main-button">ДА, ЭТО ВЕРНЫЙ ОТВЕТ</button><button type="button" className="flow-danger-button">НЕТ, ОТКЛОНИТЬ</button><small className="flow-attempt-note">ВАШЕ РЕШЕНИЕ ЗАВЕРШИТ РАУНД</small>
      </div>
    );
    if (phase === "result") return (
      <div className="flow-phone-body flow-result">
        <span className="flow-kicker">ДЕЛО ЗАКРЫТО</span><div className="flow-success-ring"><Glyph name="civilian" size={62}/></div><h3>Шпион раскрыт</h3><p>Большинство верно определило подозреваемого.</p><div className="flow-result-grid"><div><span>ШПИОН</span><b>ЛЕНА</b></div><div><span>СЛОВО</span><b>АЭРОДРОМ</b></div></div><div className="flow-vote-summary"><span>5 ИЗ 8 ГОЛОСОВ</span><i><b style={{width:"62%"}}/></i></div><button type="button" className="flow-main-button">НОВОЕ СЛОВО</button>
      </div>
    );
    return (
      <div className="flow-phone-body flow-over">
        <span className="flow-kicker">ОПЕРАЦИЯ ЗАВЕРШЕНА</span><div className="flow-end-mark"><Glyph name="agent" size={74}/><i/></div><h3>Никому нельзя доверять</h3><p>Все раунды завершены. Ведущий может закрыть комнату или начать новую операцию.</p><div className="flow-stats"><div><b>4</b><span>РАУНДА</span></div><div><b>3</b><span>ШПИОНА НАЙДЕНО</span></div><div><b>1</b><span>ПОБЕДА ШПИОНА</span></div></div><button type="button" className="flow-main-button">ЗАВЕРШИТЬ ИГРУ</button>
      </div>
    );
  })();
  return <div className="flow-phone-screen"><FlowPhoneHeader phase={flowPhases.find(item=>item.id===phase)?.label ?? ""} round={phase === "gameOver" ? "ИТОГИ" : phase === "mode" ? "НАСТРОЙКА" : "РАУНД 1"}/>{body}<footer className="flow-phone-footer"><i/> SECURE PARTY NETWORK</footer></div>;
}

function TvTop({ phase, right = "8 УЧАСТНИКОВ" }: { phase: string; right?: string }) {
  return <header className="flow-tv-header"><div><Glyph name="agent" size={38}/><span><b>ШПИОН</b><small>ОПЕРАТИВНЫЙ ЦЕНТР</small></span></div><p><span>ТЕКУЩИЙ ЭТАП</span><b>{phase}</b></p><em><i/> {right}</em></header>;
}

function TvFooter({ center = "КТО-ТО ЗА СТОЛОМ ЛЖЁТ" }: { center?: string }) {
  return <footer className="flow-tv-footer"><span>ДЕЛО 01 · РАУНД 1</span><b>{center}</b><span>СИГНАЛ СТАБИЛЕН</span></footer>;
}

function TvCanvasArt() {
  return <svg className="flow-tv-canvas-art" viewBox="0 0 700 500"><path d="M90 430h520M235 425l48-245h134l48 245M283 180l67-112 67 112M260 273h180M250 332h200M350 68V22M350 22l140 45M145 124l108 77M555 124l-108 77"/></svg>;
}

function FlowTv({ phase }: { phase: FlowPhaseId }) {
  const players = ["Анастасия", "Максим", "Лена", "Сергей", "Игорь", "Маша", "Денис", "Олег"];
  const content = (() => {
    if (phase === "mode") return <div className="flow-tv-center flow-tv-wait"><div className="flow-radar"><Glyph name="agent" size={112}/><i/><i/><i/></div><span>ОПЕРАЦИЯ ЕЩЁ НЕ НАЧАЛАСЬ</span><h3>Ожидаем решения ведущего</h3><p>На телефоне ведущего выбирается режим игры.</p></div>;
    if (phase === "briefing") return <div className="flow-tv-center flow-tv-brief"><span>СЕКРЕТНЫЕ ДАННЫЕ ОТПРАВЛЕНЫ</span><h3>Проверьте свои телефоны</h3><p>Один участник не получил слово. Не показывайте экран соседям.</p><div className="flow-ready-grid">{players.map((name,index)=><div key={name} className={index<6?"ready":""}><i>{name[0]}</i><b>{name}</b><span>{index<6?"ГОТОВ":"ОЖИДАЕМ"}</span></div>)}</div><div className="flow-ready-total"><i><b style={{width:"75%"}}/></i><span>6 / 8</span></div></div>;
    if (phase === "question") return <div className="flow-tv-question"><div className="flow-tv-timer"><svg viewBox="0 0 250 250"><circle cx="125" cy="125" r="108"/><circle className="progress" cx="125" cy="125" r="108"/></svg><b>04:12</b><span>ДО ГОЛОСОВАНИЯ</span></div><div className="flow-interview"><span>АКТИВНЫЙ ДОПРОС</span><div><i>А</i><p><small>ЗАДАЁТ ВОПРОС</small><b>АНАСТАСИЯ</b></p></div><em>→</em><div className="target"><i>М</i><p><small>ОТВЕЧАЕТ</small><b>МАКСИМ</b></p></div><small>Опишите слово, не называя его</small></div><aside>{players.slice(0,5).map((name,index)=><div key={name} className={index===0?"active":""}><i>{index+1}</i><b>{name}</b><span>{index===0?"ГОВОРИТ":index===1?"СЛЕДУЮЩИЙ":"ОЖИДАЕТ"}</span></div>)}</aside></div>;
    if (phase === "draw") return <div className="flow-tv-draw"><div className="flow-draw-meta"><span><i/> LIVE CANVAS</span><b>00:38</b></div><TvCanvasArt/><div className="flow-drawer"><span>РИСУЕТ</span><b>АНАСТАСИЯ</b><small>СЛЕДУЮЩИЙ · МАКСИМ</small></div><div className="flow-draw-order">{players.slice(0,6).map((name,index)=><i key={name} className={index===0?"active":""}>{name[0]}</i>)}</div></div>;
    if (phase === "discussion") return <div className="flow-tv-center flow-tv-discussion"><span>ОБЩИЙ КАНАЛ ОТКРЫТ</span><div className="flow-tv-wide-timer">01:34</div><h3>Обсудите подозреваемых</h3><p>Сопоставьте ответы и рисунки. Голосование начнётся после сигнала ведущего.</p><div className="flow-wave">{Array.from({length:36},(_,index)=><i key={index} style={{height:`${18 + ((index*17)%66)}px`}}/>)}</div></div>;
    if (phase === "voting") return <div className="flow-tv-voting"><div><span>ГОЛОСОВАНИЕ ИДЁТ</span><h3>Кто здесь шпион?</h3><p>Личный выбор каждого остаётся скрытым до завершения голосования.</p><div className="flow-vote-counter"><i><b style={{width:"62%"}}/></i><span>5 / 8</span></div></div><div className="flow-vote-avatars">{players.map((name,index)=><div key={name} className={index<5?"done":""}><i>{name[0]}</i><b>{name}</b><span>{index<5?"ГОЛОС ПРИНЯТ":"ОЖИДАЕМ"}</span></div>)}</div></div>;
    if (phase === "spyGuess") return <div className="flow-tv-center flow-tv-spy"><div className="flow-alert-orbit"><Glyph name="agent" size={98}/></div><span>ЛИЧНОСТЬ УСТАНОВЛЕНА</span><h3>Лена оказалась шпионом</h3><p>У неё остался последний шанс угадать секретное слово.</p><div className="flow-tv-category-card"><span>КАТЕГОРИЯ</span><b>ПУТЕШЕСТВИЯ</b><small>ОТВЕТ ВВОДИТСЯ НА ТЕЛЕФОНЕ</small></div></div>;
    if (phase === "verdict") return <div className="flow-tv-center flow-tv-verdict"><span>ОТВЕТ ПЕРЕДАН НА ПРОВЕРКУ</span><h3>Ожидаем решение Максима</h3><p>Автоматическая проверка не нашла точного совпадения.</p><div className="flow-tv-compare"><div><span>ВЕРСИЯ ШПИОНА</span><b>АЭРОПОРТ</b></div><i>?</i><div><span>СЕКРЕТНОЕ СЛОВО</span><b>СКРЫТО</b></div></div><small>ТОЛЬКО ПРОВЕРЯЮЩИЙ ВИДИТ ОБА СЛОВА</small></div>;
    if (phase === "result") return <div className="flow-tv-result"><div className="flow-result-banner"><Glyph name="civilian" size={52}/><span><small>ОПЕРАЦИЯ УСПЕШНА</small><b>ШПИОН РАСКРЫТ</b></span></div><div className="flow-result-cards"><div><span>ШПИОНОМ БЫЛА</span><i>Л</i><b>ЛЕНА</b><small>5 ИЗ 8 ГОЛОСОВ</small></div><div><span>СЕКРЕТНОЕ СЛОВО</span><small>ПУТЕШЕСТВИЯ</small><b>АЭРОДРОМ</b><em>ШПИОН НЕ УГАДАЛ</em></div></div></div>;
    return <div className="flow-tv-center flow-tv-over"><div className="flow-end-mark"><Glyph name="agent" size={116}/><i/></div><span>ВСЕ ДЕЛА ЗАКРЫТЫ</span><h3>Операция завершена</h3><p>Спасибо за игру. Никому нельзя доверять.</p><div className="flow-tv-stats"><div><b>4</b><span>РАУНДА</span></div><div><b>3</b><span>ШПИОНА НАЙДЕНО</span></div><div><b>1</b><span>ПОБЕДА ШПИОНА</span></div></div></div>;
  })();
  const phaseName = flowPhases.find(item=>item.id===phase)?.label ?? "";
  return <div className="flow-tv-screen"><div className="flow-tv-grid"/><TvTop phase={phaseName} right={phase==="voting"?"5 ИЗ 8 ПРОГОЛОСОВАЛИ":phase==="gameOver"?"ОПЕРАЦИЯ ЗАКРЫТА":"8 УЧАСТНИКОВ"}/>{content}<TvFooter center={phase==="gameOver"?"АРХИВ СОХРАНЁН":phase==="result"?"ДЕЛО ЗАКРЫТО":"КТО-ТО ЗА СТОЛОМ ЛЖЁТ"}/></div>;
}

function OperationsFullFlow() {
  const [phase, setPhase] = useState<FlowPhaseId>("mode");
  const current = flowPhases.find(item => item.id === phase)!;
  return (
    <section id="operations-full-flow" className="operations-flow-section">
      <div className="operations-flow-heading"><span>УТВЕРЖДЁННОЕ НАПРАВЛЕНИЕ · ПОЛНЫЙ СЦЕНАРИЙ</span><h2>Оперативный центр</h2><p>Все ключевые состояния телефона и TV собраны в последовательность. Переключайте этапы, чтобы проверить весь ритм расследования до интеграции в игру.</p></div>
      <nav className="operations-flow-nav" aria-label="Этапы игры Шпион">{flowPhases.map(item=><button key={item.id} type="button" aria-pressed={phase===item.id} onClick={()=>setPhase(item.id)}><span>{item.number}</span><Glyph name={item.icon} size={22}/><b>{item.label}</b><small>{item.detail}</small></button>)}</nav>
      <div className="operations-current"><span>{current.number}</span><div><b>{current.label}</b><p>{current.detail}</p></div></div>
      <div className="operations-flow-devices">
        <div className="spy-device-column"><DeviceLabel/><div className="spy-phone-shell"><FlowPhone phase={phase}/></div></div>
        <div className="spy-device-column spy-tv-column"><DeviceLabel tv/><div className="spy-tv-shell"><FlowTv phase={phase}/></div></div>
      </div>
      <div className="operations-coverage"><span><i/> 10 ЭТАПОВ</span><span><i/> 2 РЕЖИМА</span><span><i/> MOBILE + TV</span><b>ТОЛЬКО МАКЕТЫ · ЛОГИКА НЕ ИЗМЕНЕНА</b></div>
    </section>
  );
}

function IconMenu() {
  const [active, setActive] = useState<IconFamily>("signal");
  const current = iconFamilies.find(item => item.id === active)!;
  return (
    <section id="icons" className="spy-icons-section">
      <div className="spy-icons-heading"><span>ОТДЕЛЬНОЕ МЕНЮ</span><h2>Язык иконок</h2><p>Иконки можно оценивать независимо от общей концепции и затем смешать с выбранным визуальным направлением.</p></div>
      <div className="spy-icon-tabs">{iconFamilies.map(item => <button key={item.id} type="button" aria-pressed={active === item.id} onClick={() => setActive(item.id)}><b>{item.name}</b><span>{item.description}</span></button>)}</div>
      <div className={`spy-icon-board icon-board-${active}`}>
        <header><span>ВЫБРАНО</span><h3>{current.name}</h3><p>{current.description}</p></header>
        <div>{(Object.keys(iconLabels) as IconName[]).map(name => <figure key={name}><span><Glyph name={name} family={active} size={54}/></span><figcaption>{iconLabels[name]}</figcaption></figure>)}</div>
        <footer><span>МАЛЫЙ РАЗМЕР</span>{(Object.keys(iconLabels) as IconName[]).map(name => <Glyph key={name} name={name} family={active} size={24}/>)}</footer>
      </div>
    </section>
  );
}

